input.content:
workspace "Energy Manager" "A platform for managing a household's energy use and costs." {
    model {
        homeowner = person "Homeowner" "A homeowner who uses the platform to manage their household's energy use and costs."

        energyManager = softwareSystem "Energy Manager" "A platform for managing a household's energy use and costs, owned and operated by our company." {
            dashboard = container "Dashboard Web App" "A web app where homeowners see consumption and costs. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Web App"
            scheduling = container "Scheduling Service" "A service that plans charging and heating. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Service"
            database = container "Database" "A database that stores meter readings and schedules, operated by our company." "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "Provides live meter readings, operated by a different organization." "External"

        homeowner -> energyManager "manages household energy use and costs" "HTTPS/JSON"
        homeowner -> dashboard "views consumption and costs" "HTTPS/JSON"
        scheduling -> smartMeterProvider "fetches live meter readings from" "HTTPS/JSON"
        scheduling -> database "stores meter readings and schedules in" "SQL"
    }

    views {
        systemContext energyManager "System Context" {
            include *
            autoLayout
        }

        container energyManager "Container" {
            include *
            autoLayout
        }
    }
}

